// ============================================================================
// ENGLISH GRADE 8, THE QUESTION SKILLS THE DEPTH PASS LEFT WITHOUT A FAMILY (19 Nov 2026, the questions wave,
// Tuta Workspace/HOREB_QUESTIONS_PLAN.md): telephone and interview manners, polite disagreement, connectors and sequence,
// reading strategies, reference materials, dialogue and repetition, visuals, characters and relationships, the writing
// process, myths, inanimate characters in poems and idioms in context. DRAFT families.
// Written offline, no model call. Every sentence, extract, myth and poem line is original, with Kenyan names and places.
// Every wrong answer carries the library misconception behind it (curriculum/english/g8.json). Off for children
// (reviewed:false) until a Kenyan English teacher signs them off. Conducting a call or an interview, and speaking in a
// discussion, are still heard by a teacher (docs/qa/english-g8-non-question-outcomes-2026-11-13.md); these test the words.
// ============================================================================
import { eng, choose, spot, mc, feedbackOf, shuffle, pick, randInt } from './english_g8_lib.js';

const K = (c) => `M8_X_${c}`;
const x = (t, c) => [t, K(c)];
const w = (c, ...xs) => xs.map(t => x(t, c));
const I = (text, right, wrongs, because) => [text, right, ...wrongs, because];
const L = (label, it) => Object.assign(it, { label });
const H = (a, b) => [a, b];
const C = (key, kind, cs, pool, { stem = 'Choose.', hints, oc = 'a', rung = 1 }) =>
  eng({ id: `english8.${key}`, kind, cs, oc, form: 'direct', rung, gen: choose(pool, { stem, hints }) });
const SP = (key, cs, pool, { topic, hints, oc = 'a', rung = 3 }) =>
  eng({ id: `english8.${key}.spot`, kind: 'spot', cs, oc, form: 'spot', rung, gen: spot(pool, { topic, hints }) });

// Put four sentences or events in order: options are lists of letters (as english_g7_write.js).
const orderGen = (sets, { intro, codes, hints }) => (cskill) => {
  const ev = pick(sets);
  let show; do { show = shuffle(ev.map((t, i) => i)); } while (show.every((v, i) => v === i));
  const letter = (idx) => 'ABCD'[show.indexOf(idx)];
  const seq = (arr) => arr.map(letter).join(', ');
  const base = [0, 1, 2, 3], right = seq(base), i = randInt(0, 2), sw = [...base]; [sw[i], sw[i + 1]] = [sw[i + 1], sw[i]];
  const options = mc(right, [[seq([...base].reverse()), feedbackOf(cskill, codes[0]), codes[0]], [seq(sw), feedbackOf(cskill, codes[1]), codes[1]], [seq([3, 0, 1, 2]), feedbackOf(cskill, codes[0]), codes[0]]]);
  if (!options) return null;
  const list = show.map((idx, k) => `${'ABCD'[k]} ${ev[idx]}`).join(' ');
  return { question: `${intro} ${list}`, options, fixedOrder: false, instruction: 'Choose the best answer.', hints, steps: [`The right order is: ${ev.map((t, k) => `${k + 1}. ${t}`).join(' ')}`, `Written as letters this is ${right}.`], chk: () => true };
};
const OR = (key, kind, cs, sets, { intro, codes, hints, oc = 'a', rung = 2 }) =>
  eng({ id: `english8.${key}`, kind, cs, oc, form: 'direct', rung, gen: orderGen(sets, { intro, codes: codes.map(K), hints }) });

