// ---------------------------------------------------------------- connectors and sequence
const PC_CS = 'WRITIN.T3_PARAGRAPHING_SEQUENC.PARAGRAPH_CONNECTORS';
const PC_GAP = [
  I('First, we cleared the land. ___, we planted the tree seedlings in rows.', 'Next|Then|After that', [x('However', 'PC_WRONG_CONNECTOR'), x('Finally', 'PC_FINALLY_FIRST'), x('Although', 'PC_WRONG_CONNECTOR')], 'The second step comes next, so a connector of sequence is needed.'),
  I('We boiled the water, cooled it and poured it into clean bottles. ___, we stored the bottles in a cool place.', 'Finally|Lastly', [x('First', 'PC_FINALLY_FIRST'), x('However', 'PC_WRONG_CONNECTOR'), x('Instead', 'PC_WRONG_CONNECTOR')], 'This is the last step, so "Finally" fits.'),
  I('The rains failed for two seasons. ___, many farmers lost their crops.', 'As a result|Therefore', [x('However', 'PC_WRONG_CONNECTOR'), x('First', 'PC_FINALLY_FIRST'), x('Although', 'PC_WRONG_CONNECTOR')], 'The second sentence is the result of the first.'),
  I('___, mix the flour with a little water. Then knead the dough and roll it out for chapati.', 'First|Firstly', [x('Finally', 'PC_FINALLY_FIRST'), x('However', 'PC_WRONG_CONNECTOR'), x('As a result', 'PC_WRONG_CONNECTOR')], 'This is the first step of the recipe.'),
  I('We swept the classroom. ___ we had swept it, we arranged the desks neatly.', 'After|Once', [x('However', 'PC_WRONG_CONNECTOR'), x('Finally', 'PC_FINALLY_FIRST'), x('Although', 'PC_WRONG_CONNECTOR')], 'Arranging the desks came after sweeping, so "After" shows the sequence.'),
];
