// ---------------------------------------------------------------- characters and their relationships
const CR_CS = 'READIN.T7_INTENSIVE_READING_SH.CHARACTER_RELATIONS';
const CR_REL = [
  I('In a story, old Mzee Tole teaches young Juma to carve wood, and Juma visits him every evening to learn more. How are Mzee Tole and Juma related in the story.', 'mentor and learner', w('CR_RELATION_WRONG', 'rivals', 'enemies', 'brothers'), 'Mzee Tole teaches and Juma learns: they are mentor and learner.'),
  I('In a story, Achieng and Rose both want to be the fastest runner in the county, and each trains hard to beat the other. How are they related in the story.', 'rivals', w('CR_RELATION_WRONG', 'mentor and learner', 'mother and daughter', 'teacher and learner'), 'They compete for the same thing, so they are rivals.'),
  I('At the start of a story, Neema and Rose are best friends. They quarrel over a lost book, and in the end Rose finds it and they make peace. How does their relationship change.', 'from friends, to enemies, to friends again', [x('it does not change', 'CR_STATIC'), x('they are enemies all through', 'CR_STATIC'), x('they are friends all through, with no quarrel', 'CR_STATIC')], 'Follow the relationship from the start to the end: it changes twice.'),
  I('In a story, Kipchoge looks down on his new neighbour, but after the neighbour saves his cows from a fire, they become close. How does their relationship change.', 'from distrust to friendship', [x('it stays the same', 'CR_STATIC'), x('from friendship to distrust', 'CR_RELATION_WRONG'), x('they are rivals all through', 'CR_STATIC')], 'At first he looks down on the neighbour; after the fire they become close.'),
  I('In a story, Baraka always shares his food with his little cousin Tom and walks him to school. How are Baraka and Tom related in the story.', 'cousins who care for each other', w('CR_RELATION_WRONG', 'rivals', 'enemies', 'strangers'), 'The story says they are cousins, and Baraka cares for Tom.'),
];
const CR_TRAIT = [
  I('A story says: "Amina gave her last coin to the blind man at the gate, though she had not eaten all day." Which is the best description of Amina.', 'Amina is generous: she gives her last coin to the blind man.', [x('Amina is generous.', 'CR_TRAIT_NO_EVIDENCE'), x('Amina is rich and likes to show off her money at the gate.', 'CR_TRAIT_NO_EVIDENCE'), x('Amina is lazy.', 'CR_TRAIT_NO_EVIDENCE')], 'A good description gives the trait and the evidence from the story.'),
  I('A story says: "Odhiambo stayed behind after the match to pick up every bottle on the field." Which is the best description of Odhiambo.', 'Odhiambo is responsible: he stays to clean the field.', [x('Odhiambo is responsible.', 'CR_TRAIT_NO_EVIDENCE'), x('Odhiambo is a good footballer who likes to play every day.', 'CR_TRAIT_NO_EVIDENCE'), x('Odhiambo is tired.', 'CR_TRAIT_NO_EVIDENCE')], 'Give the trait and the action that shows it.'),
  I('A story says: "Wanjiru laughed at the new girl\'s torn shoes and told the whole class." Which is the best description of Wanjiru.', 'Wanjiru is unkind: she laughs at the new girl\'s shoes.', [x('Wanjiru is unkind.', 'CR_TRAIT_NO_EVIDENCE'), x('Wanjiru is a funny girl who likes to make the class laugh.', 'CR_TRAIT_NO_EVIDENCE'), x('Wanjiru is clever.', 'CR_TRAIT_NO_EVIDENCE')], 'The evidence is what she does to the new girl.'),
  I('A story says: "Though the river was rising, Mutua waded in to pull the small boy out." Which is the best description of Mutua.', 'Mutua is brave: he goes into the rising river to save the boy.', [x('Mutua is brave.', 'CR_TRAIT_NO_EVIDENCE'), x('Mutua can swim very well, and he likes to play in the river.', 'CR_TRAIT_NO_EVIDENCE'), x('Mutua is careless.', 'CR_TRAIT_NO_EVIDENCE')], 'A trait is backed up by what the character does.'),
  I('A story follows Chebet as she trains for a race and wins it. A shopkeeper appears once to sell her a pair of shoes. Who is the main character.', 'Chebet', [x('the shopkeeper', 'CR_MINOR_MAIN'), x('the person who sells the shoes', 'CR_MINOR_MAIN'), x('the crowd at the race', 'CR_MINOR_MAIN')], 'The main character is the one the story follows from the start to the end.'),
  I('A story follows Musa as he looks for his lost goat. On the way he asks a herdsman, who points to the hills. Who is the main character.', 'Musa', [x('the herdsman', 'CR_MINOR_MAIN'), x('the person who points to the hills', 'CR_MINOR_MAIN'), x('the people Musa meets', 'CR_MINOR_MAIN')], 'Musa is the one the story follows; the herdsman appears only once.'),
];
