// ---------------------------------------------------------------- myths
const MY_CS = 'LISTEN.T8_LISTENING_AND_RESPON.MYTHS';
const MY_WHO = [
  I('In a myth, the Creator sends the first rain to the first people from the top of a mountain. What kind of character is the Creator.', 'a god who made the world', w('MY_CHARACTER_TYPE', 'an ordinary old man', 'a clever animal', 'a brave warrior'), 'In a myth, characters are often gods, spirits or the first people.'),
  I('A story tells how the first people got fire from the sky. What kind of story is it.', 'a myth, because it explains how something began', [x('a legend, because it is old', 'MY_LEGEND_MYTH'), x('a legend, because it has people in it', 'MY_LEGEND_MYTH'), x('a news report', 'MY_LEGEND_MYTH')], 'A myth explains how something in the world began, often with gods or spirits.'),
  I('In a myth, the Spirit of the Lake grows angry and sends a great storm. What kind of character is the Spirit of the Lake.', 'a spirit with power over nature', w('MY_CHARACTER_TYPE', 'an ordinary fisherman', 'a small child', 'a village elder'), 'A spirit in a myth has power that people do not have.'),
  I('A story tells of a brave woman who led her people across a river long ago. It does not explain how anything began. What kind of story is it.', 'a legend', [x('a myth', 'MY_LEGEND_MYTH'), x('a myth, because it is old', 'MY_LEGEND_MYTH'), x('a myth, because it has a river', 'MY_LEGEND_MYTH')], 'A legend is about a hero of the past. A myth explains how something began.'),
  I('A story explains why the sun and the moon never meet in the sky. What kind of story is it.', 'a myth', [x('a legend', 'MY_LEGEND_MYTH'), x('a legend, because it is about the sky', 'MY_LEGEND_MYTH'), x('a riddle', 'MY_LEGEND_MYTH')], 'It explains something in nature, so it is a myth.'),
];
const MY_LESSON = [
  I('A myth tells that the moon was once as bright as the sun, but it boasted, so the Creator dimmed its light. What lesson does it teach.', 'pride brings a fall', w('MY_LITERAL_LESSON', 'why the moon is dim', 'the moon is beautiful', 'the sun is bright'), 'Look beyond what the myth explains to the lesson about how to live.'),
  I('A myth tells that the first people were given all the cattle in the world, but they quarrelled over them, so the cattle ran away to the forest and became wild buffalo. What lesson does it teach.', 'greed and quarrels bring loss', w('MY_LITERAL_LESSON', 'why buffalo live in the forest', 'cattle can run fast', 'the forest is large'), 'The myth explains the buffalo, but its lesson is about greed.'),
  I('A myth tells that the tortoise was once fast, but it laughed at the slow ants, so the Creator made it the slowest of all. What lesson does it teach.', 'do not laugh at those who are weaker than you', w('MY_LITERAL_LESSON', 'why the tortoise is slow', 'ants are small', 'tortoises have shells'), 'The lesson is about how the tortoise behaved, not only why it is slow.'),
  I('A myth tells that the river once flowed to every home, but people threw rubbish into it, so it hid underground. What lesson does it teach.', 'take care of what you are given', w('MY_LITERAL_LESSON', 'why some rivers are underground', 'rivers are long', 'people need water'), 'The myth explains the river, but its lesson is about care.'),
  I('A myth tells that the first man and woman were told not to eat the fruit of one tree. They ate it, and from that day people have had to work for their food. What lesson does it teach.', 'disobedience brings suffering', w('MY_LITERAL_LESSON', 'why people work for their food', 'the fruit was sweet', 'trees give fruit'), 'The lesson is about obeying, not only about why people work.'),
];
const MY_ORDER = [
  ['In the beginning, the Creator lived on top of the highest mountain.', 'He made the first man and woman from the red soil.', 'He gave them cattle and seeds to plant.', 'Ever since, people have faced the mountain when they pray.'],
  ['Long ago, the sun and the moon were friends who walked together.', 'One day the moon boasted that it was more beautiful.', 'The angry sun threw mud at the moon\'s face.', 'That is why the moon has dark marks and walks alone at night.'],
  ['At first, the tortoise was the fastest animal.', 'It laughed at the slow ants every day.', 'The Creator heard and was displeased.', 'Since then, the tortoise has been the slowest of all.'],
];
// ---------------------------------------------------------------- inanimate characters in a poem
const IC_CS = 'READIN.T8_INTENSIVE_READING_PO_2.INANIMATE_CHARACTERS';
const IC_WHO = [
  I('Which is the inanimate character in these lines: "The old baobab watched the village sleep, / While a lion roared far away."', 'the baobab', [x('the lion', 'IC_ANIMALS'), x('the village', 'IC_MISSES'), x('there is none', 'IC_MISSES')], 'An inanimate character is a thing that is not alive, given human actions: the baobab watches.'),
  I('Which is the inanimate character in these lines: "The sun smiled on the beach at Malindi, / And the children ran into the waves."', 'the sun', [x('the children', 'IC_MISSES'), x('the beach', 'IC_MISSES'), x('there is none', 'IC_MISSES')], 'The sun is not alive, but it smiles like a person.'),
  I('Which is the inanimate character in these lines: "The tired bus groaned up the hill to Iten, / As the goats looked on from the road."', 'the bus', [x('the goats', 'IC_ANIMALS'), x('the hill', 'IC_MISSES'), x('there is none', 'IC_MISSES')], 'The bus is a thing, but it is tired and it groans like a person.'),
  I('Which is the inanimate character in these lines: "The wind whispered secrets to the maize, / And the cock crowed at dawn."', 'the wind', [x('the cock', 'IC_ANIMALS'), x('the dawn', 'IC_MISSES'), x('there is none', 'IC_MISSES')], 'The wind whispers like a person, so it is an inanimate character.'),
  I('Which is the inanimate character in these lines: "My drum laughs when the dancers come, / And the dog barks at the noise."', 'the drum', [x('the dog', 'IC_ANIMALS'), x('the dancers', 'IC_MISSES'), x('there is none', 'IC_MISSES')], 'The drum is a thing that laughs like a person.'),
  I('Which is the inanimate character in these lines: "The mountain wore a white cap of cloud / And looked down on the town of Nanyuki."', 'the mountain', [x('the town of Nanyuki', 'IC_MISSES'), x('there is none', 'IC_MISSES'), x('the people of the town', 'IC_MISSES')], 'The mountain wears a cap and looks down, as a person does.'),
];
const IC_TRAIT = [
  I('"The river hugged the little village / And sang it to sleep each night." What is the river like in these lines.', 'loving and caring', [x('cruel and angry', 'IC_TRAIT_WRONG'), x('it is a real singer', 'IC_LITERAL'), x('lazy and slow', 'IC_TRAIT_WRONG')], 'Hugging and singing to sleep are loving, caring actions.'),
  I('"The angry sea threw the boats onto the rocks / And roared at the fishermen." What is the sea like in these lines.', 'angry and dangerous', [x('gentle and kind', 'IC_TRAIT_WRONG'), x('the sea really shouts words', 'IC_LITERAL'), x('happy and playful', 'IC_TRAIT_WRONG')], 'Throwing boats and roaring show the sea is angry and dangerous.'),
  I('"The old clock coughed and dragged its hands / Slowly round to twelve." What is the clock like in these lines.', 'old, tired and slow', [x('young and fast', 'IC_TRAIT_WRONG'), x('the clock is really sick', 'IC_LITERAL'), x('angry and cruel', 'IC_TRAIT_WRONG')], 'Coughing and dragging slowly make the clock seem old and tired.'),
  I('"The tall tree spread its arms over us / To keep away the burning sun." What is the tree like in these lines.', 'protective', [x('cruel', 'IC_TRAIT_WRONG'), x('the tree really has arms', 'IC_LITERAL'), x('selfish', 'IC_TRAIT_WRONG')], 'The tree keeps the sun away from the people, so it is protective.'),
  I('"The proud road ran ahead of us, / Never stopping to wait." What is the road like in these lines.', 'proud and impatient', [x('humble and patient', 'IC_TRAIT_WRONG'), x('the road really runs', 'IC_LITERAL'), x('kind and gentle', 'IC_TRAIT_WRONG')], 'The road is called proud, and it never waits, so it is impatient.'),
];
// ---------------------------------------------------------------- idioms in context
const ID_CS = 'WRITIN.T13_CREATIVE_NARRATIVE_C.IDIOMS_CONTEXT';
const ID_MEAN = [
  I('"The new phone cost Juma an arm and a leg." What does the idiom mean here.', 'it was very expensive', [x('it cost him parts of his body', 'IC2_LITERAL'), x('it was very cheap', 'IC2_OPPOSITE'), x('it hurt his arm', 'IC2_LITERAL')], '"An arm and a leg" means a very high price.'),
  I('"Losing the first race was a blessing in disguise for Akinyi: she trained harder and won the county title." What does the idiom mean here.', 'a bad thing that led to something good', [x('a hidden prayer', 'IC2_LITERAL'), x('a good thing that led to something bad', 'IC2_OPPOSITE'), x('a gift wrapped in paper', 'IC2_LITERAL')], 'A blessing in disguise looks bad at first but brings something good.'),
  I('"The Grade 8 test was a piece of cake for Otieno." What does the idiom mean here.', 'it was very easy', [x('it was a cake he ate', 'IC2_LITERAL'), x('it was very hard', 'IC2_OPPOSITE'), x('it was sweet', 'IC2_LITERAL')], '"A piece of cake" means something very easy.'),
  I('"Please do not let the cat out of the bag about the surprise party for our teacher." What does the idiom mean here.', 'tell a secret', [x('free a cat from a bag', 'IC2_LITERAL'), x('keep a secret', 'IC2_OPPOSITE'), x('buy a cat at the market', 'IC2_LITERAL')], 'To let the cat out of the bag is to tell a secret by mistake.'),
  I('"After the long walk from the river, Wanjiku was ready to call it a day." What does the idiom mean here.', 'stop working and rest', [x('give the day a name', 'IC2_LITERAL'), x('start working harder', 'IC2_OPPOSITE'), x('telephone someone during the day', 'IC2_LITERAL')], '"Call it a day" means to stop work for now.'),
  I('"Mutua was over the moon when he was chosen as school captain." What does the idiom mean here.', 'very happy', [x('very sad', 'IC2_OPPOSITE'), x('high up in the sky', 'IC2_LITERAL'), x('jumping over the moon', 'IC2_LITERAL')], '"Over the moon" means very happy.'),
];
const ID_FIT = [
  I('Losing the race was ___: it made Akinyi train harder and win the county title.', 'a blessing in disguise', [x('a piece of cake', 'IC2_WRONG_FIT'), x('a blessing in hiding', 'IC2_CHANGED'), x('the last straw', 'IC2_WRONG_FIT')], 'A bad thing that led to a good thing is a blessing in disguise.'),
  I('The new school bus cost ___, so the parents had to hold a fundraiser.', 'an arm and a leg', [x('an arm and a hand', 'IC2_CHANGED'), x('a piece of cake', 'IC2_WRONG_FIT'), x('over the moon', 'IC2_WRONG_FIT')], 'Something very expensive costs an arm and a leg.'),
  I('The sums were so easy that the test was ___ for the whole class.', 'a piece of cake', [x('a slice of cake', 'IC2_CHANGED'), x('an arm and a leg', 'IC2_WRONG_FIT'), x('a blessing in disguise', 'IC2_WRONG_FIT')], 'Something very easy is a piece of cake.'),
  I('Baraka was ___ when his mother bought him a new bicycle.', 'over the moon', [x('over the sun', 'IC2_CHANGED'), x('a piece of cake', 'IC2_WRONG_FIT'), x('under the weather', 'IC2_WRONG_FIT')], 'Someone very happy is over the moon.'),
  I('Do not ___ about the surprise party; Mama must not know.', 'let the cat out of the bag', [x('let the dog out of the bag', 'IC2_CHANGED'), x('call it a day', 'IC2_WRONG_FIT'), x('cost an arm and a leg', 'IC2_WRONG_FIT')], 'To tell a secret is to let the cat out of the bag.'),
  I('We have dug for six hours. Let us ___ and finish tomorrow.', 'call it a day', [x('call it a night', 'IC2_CHANGED'), x('let the cat out of the bag', 'IC2_WRONG_FIT'), x('be over the moon', 'IC2_WRONG_FIT')], 'To stop work for now is to call it a day.'),
];

